    zr=[r for r in range(H) if (A[r]==0).all()]
    zc=[c for c in range(W) if (A[:,c]==0).all()]
    out=A.copy()
    rr=[]; prev=0
    for r in zr+[H]:
        if r>prev: rr.append((prev,r)); prev=r+1
    cc=[]; prev=0
    for c in zc+[W]:
        if c>prev: cc.append((prev,c)); prev=c+1
    for r0,r1 in rr:
        for c0,c1 in cc:
            vals={v for v in out[r0:r1,c0:c1].flat if v not in (0,5)}
